import './Login.css';
import NavigationBar from './NavigationBar';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import React, { useState } from 'react';
import axios from 'axios';

const CreatePost = ({ post, refreshPosts }) => {
    const [content, setContent] = useState("");
    const [error, setError] = useState("");
    const token = localStorage.getItem('token');
    const userId = localStorage.getItem("userId");

    console.log("Retrieved userId:", userId); // Debugging

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");

        const token = localStorage.getItem("authToken");
        if (!token) {
            setError("You must be logged in to create a post.");
            return;
        }

        // try {
        //     if (post) {
        //       // Update existing post
        //       await axios.put(
        //         `http://localhost:8080/api/posts/${post.id}/update`,
        //         { content },
        //         { headers: { Authorization: `Bearer ${token}` } }
        //       );
        //     } else {
        //       // Create new post – backend expects a JSON with content and a user object having an id
        //       await axios.post(
        //         'http://localhost:8080/api/posts/create',
        //         { content, user: { id: userId } },
        //         { headers: { Authorization: `Bearer ${token}` } }
        //       );
        //     }
        //     setContent('');
        //     refreshPosts();
        //   } catch (error) {
        //     console.error(error);
        //   }

        try {
            const response = await fetch("http://localhost:6543/api/posts/create", {
                method: "POST",
                headers: {
                    Authorization: `Bearer ${token}`,
                    "Content-Type": "application/json",
                    "Accept": "application/json",
                },
                credentials: "include",
                body: JSON.stringify({
                    user: { id: userId },
                    content,
                }),
            });

            if (!response.ok) {
                throw new Error("Failed to create post");
            }

            const newPost = await response.json();
            console.log("Post created:", newPost);

            setContent(""); // Clear input after successful post creation
            alert("Post created successfully!");
        } catch (err) {
            console.error("Error creating post:", err);
            setError(err.message || "An error occurred.");
        }
    };

    return(
        <div fluid>
            <form action="#" method="POST" onSubmit={handleSubmit}>
                {/* <div>
                        <label for="title">Title</label>
                            <div>
                                <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Title" required/>
                            </div>
                    </div> */}
                <div>
                    <label>Content</label>
                        <div>
                            <input type="text" value={content} onChange={(e) => setContent(e.target.value)} placeholder="What's on your mind?" required/>
                        </div>
                            {error && <p style={{ color: 'red' }}>{error}</p>}
                </div>
                <div>
                    <button type="submit">Post</button>
                </div>
            </form>
        </div>
    )
}

export default CreatePost;
